package disaster.util; import java.util.*; import disaster.zone.Zone; import disaster.interfaces.ZoneFilter;
public class ZoneCatalog {private final ArrayList<Zone> zones=new ArrayList<>();private final HashSet<String> ids=new HashSet<>();private final LinkedList<Zone> rescueRequests=new LinkedList<>();public void add(Zone z){if(!ids.add(z.getId()))throw new IllegalArgumentException("Duplicate zone ID: "+z.getId());zones.add(z);}public List<Zone> filter(ZoneFilter f){List<Zone> out=new ArrayList<>();for(Zone z:zones)if(f.check(z))out.add(z);return out;}public TreeSet<Zone> priorityOrder(){return new TreeSet<>(zones);}public Queue<Zone> rescueQueue(){rescueRequests.clear();rescueRequests.addAll(priorityOrder());return rescueRequests;}public Iterator<Zone> iterator(){return zones.iterator();}}
